package com.earthtrip.notification.adapter.out.security;import com.earthtrip.notification.application.port.out.PushTokenProtectorPort;import com.earthtrip.sharedkernel.error.EarthTripException;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
@Component class AesPushTokenProtector implements PushTokenProtectorPort{private final byte[] key;private final SecureRandom random=new SecureRandom();AesPushTokenProtector(@Value("${earthtrip.push.token-encryption-key:}")String encoded){byte[]decoded;try{decoded=encoded.isBlank()?new byte[0]:Base64.getDecoder().decode(encoded);}catch(IllegalArgumentException e){decoded=new byte[0];}key=decoded;}@Override public ProtectedToken protect(String token){if(key.length!=32)throw EarthTripException.unavailable("PUSH_TOKEN_ENCRYPTION_NOT_CONFIGURED","푸시 토큰 암호화 키가 설정되지 않았습니다.");if(token==null||token.isBlank())throw EarthTripException.badRequest("PUSH_TOKEN_REQUIRED","푸시 토큰이 필요합니다.");try{byte[]iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));byte[]encrypted=c.doFinal(token.getBytes(StandardCharsets.UTF_8));byte[]joined=new byte[iv.length+encrypted.length];System.arraycopy(iv,0,joined,0,iv.length);System.arraycopy(encrypted,0,joined,iv.length,encrypted.length);return new ProtectedToken(hash(token),Base64.getEncoder().encodeToString(joined));}catch(GeneralSecurityException e){throw new IllegalStateException("푸시 토큰을 암호화할 수 없습니다.",e);}}private static String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
